package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.JdbcFrozenInputs;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.ObjectNode;
/** Pure detached immutable report identity, from an actual fictional H2 preparation. No network calls. */
class ReportBusinessInputHashTest {
 ReportNativeGenerationIntegrationTest h;
 ObjectNode original()throws Exception{h=new ReportNativeGenerationIntegrationTest();h.setup();return (ObjectNode)CanonicalJson.parse(h.h.h.original.input().snapshotJson());}
 ObjectNode supplement(ObjectNode initial){var next=initial.deepCopy();next.put("generation",2);next.put("cutoff",new java.time.format.DateTimeFormatterBuilder().appendInstant(6).toFormatter().format(WireValues.utcMicroseconds(initial.get("cutoff")).plusSeconds(10)));((ObjectNode)next.get(ReportPreparationInputProfile.FIELD)).put("explicit_supplement",true);var context=(ObjectNode)next.get(FrozenApplicationContext.FIELD);context.put("generation",2);((ObjectNode)context.get("target_content")).put("base_revision",7);return next;}
 String request(ObjectNode snapshot){return new GenerationRequestBuilder().build(ReportPreparationInputProfile.complete(snapshot).command().stage(),JdbcFrozenInputs.canonical(snapshot),CanonicalJson.hash(CanonicalJson.Domain.INPUT,snapshot));}
 String hash(ObjectNode snapshot){return ReportBusinessInputHash.hash(JdbcFrozenInputs.canonical(snapshot),request(snapshot));}
 @Test void SameBusinessAtNewCutoffGenerationAndContentRevisionKeepsIdentity()throws Exception{var old=original();var next=supplement(old);assertNotEquals(CanonicalJson.hash(CanonicalJson.Domain.INPUT,old),CanonicalJson.hash(CanonicalJson.Domain.INPUT,next));assertEquals(hash(old),hash(next));assertEquals(hash(old),ReportBusinessInputHash.hash(JdbcFrozenInputs.canonical(old),h.h.h.original.input().requestJson()));assertThrows(RuntimeException.class,()->ReportBusinessInputHash.hash(JdbcFrozenInputs.canonical(old),null));assertEquals(1,h.reportSends);}
 @Test void SemanticSettingsChangeAddsBusinessIdentityButRevisionOrOrderingDoesNot()throws Exception{var old=original();var next=supplement(old);var originalSettings=FrozenGenerationSettings.read(old.get(FrozenGenerationSettings.FIELD));next.set(FrozenGenerationSettings.FIELD,new FrozenGenerationSettings(9,originalSettings.followKeywords(),originalSettings.blockedKeywords()).toJson());assertEquals(hash(old),hash(next));var changed=new FrozenGenerationSettings(10,List.of("Fictional new preference"),List.of());next.set(FrozenGenerationSettings.FIELD,changed.toJson());next.put("settings_hash",changed.semanticHash());assertNotEquals(hash(old),hash(next));}
 @Test void ActualPreparedDefinitionAndCompleteSourceProjectionAffectIdentity()throws Exception{var old=original();var request=(ObjectNode)CanonicalJson.parse(request(old));((ObjectNode)request.get("parameters")).put("temperature",0);assertNotEquals(hash(old),ReportBusinessInputHash.hash(JdbcFrozenInputs.canonical(old),JdbcFrozenInputs.canonical(request)));var next=supplement(old);((ObjectNode)next.get(com.lianxibu.site.service.content.FrozenPublicMetadata.FIELD).get("citations").get(0)).put("title","Fictional revised citation display");assertNotEquals(hash(old),hash(next));assertEquals(64,hash(old).length());}
 @Test void WrongInputHashMessageOrMissingWholePreparationCannotHashAsValidBusiness()throws Exception{var old=original();var request=(ObjectNode)CanonicalJson.parse(request(old));request.put("input_hash","a".repeat(64));assertThrows(RuntimeException.class,()->ReportBusinessInputHash.hash(JdbcFrozenInputs.canonical(old),JdbcFrozenInputs.canonical(request)));var wrong=(ObjectNode)CanonicalJson.parse(request(old));((ObjectNode)wrong.get("messages").get(1)).put("content","{}");assertThrows(RuntimeException.class,()->ReportBusinessInputHash.hash(JdbcFrozenInputs.canonical(old),JdbcFrozenInputs.canonical(wrong)));var damaged=old.deepCopy();damaged.remove(ReportPreparationInputProfile.FIELD);assertThrows(RuntimeException.class,()->hash(damaged));}
}
